WITH enriched AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, SUM(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_sum_discount_pct, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY ends_on, id) AS row_seq, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) AS discount_pct_share, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share_2 FROM promotions) SELECT CASE WHEN discount_pct_share >= 0.64 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_share_tier, promo_code, COUNT(DISTINCT channel) AS distinct_channels, COUNT_IF(channel = 'partner') AS partner_events, COUNT_IF(promo_code = 'WELCOME5') AS welcome5_events FROM enriched GROUP BY CASE WHEN discount_pct_share >= 0.64 THEN 'PREMIUM' ELSE 'STANDARD' END, promo_code HAVING COUNT_IF(channel = 'partner') >= 1;
